#include <iostream>
#include <utility>
template <typename T>
void perfectForward(T&& param) {
  std::cout << "perfectForward called with: ";
  //std::forward<T>(param) ensures no unnecessary copies
  if constexpr(std::is_same_v<std::decay_t<T>, int>){
      std::cout << "int: " << param << std::endl;
  } else {
      param.print();
  }
}
struct MyStruct {
  int data;
  void print() { std::cout << "MyStruct: " << data << std::endl; }
  MyStruct(int d) : data(d) {}
  MyStruct(MyStruct&& other) : data(other.data){ std::cout << "MyStruct Move constructor called" << std::endl;};
  MyStruct(const MyStruct& other) : data(other.data){ std::cout << "MyStruct Copy constructor called" << std::endl;};
};
int main() {
  int i = 10;
  MyStruct obj(20);
  perfectForward(i);
  perfectForward(obj);
  perfectForward(MyStruct(30)); // rvalue
  return 0;
}
